def cleanup_stopped_probe(name):
 log=base/(name+'.log')
 for line in log.read_text(errors='replace').splitlines():
  try: proof=json.loads(line)
  except (ValueError,TypeError): continue
  if not isinstance(proof,dict) or proof.get('status')!='passed' or proof.get('stopExitCode')!=0 or not re.fullmatch(r'/tmp/doya-sfa-authority-[a-f0-9]{8}',str(proof.get('privateFolder',''))): continue
  p=pathlib.Path(proof['privateFolder'])
  if not p.exists(): continue
  assert not p.is_symlink() and p.resolve().parent==pathlib.Path('/private/tmp') and not (p/'data/postmaster.pid').exists()
  result=subprocess.run(['/opt/homebrew/opt/postgresql@17/bin/pg_ctl','-D',str(p/'data'),'status'],capture_output=True);assert result.returncode==3
  archive=base/'stopped-test-db-logs';archive.mkdir(exist_ok=True)
  for source in p.glob('*.log'):shutil.copy2(source,archive/(p.name+'-'+source.name))
  shutil.rmtree(p)
